/* cppi::324a059f443861ca9e366c70f9c36299c878964a7fcbdb34c78ef8fd19e367cb */
SELECT cppib_party_id, rating_value FROM performance.cppib_party_rating
                WHERE business_date = '2025-06-17' AND rating_agency = 'CPPIB'

/* cppi::17cddf20f256f8ef361bbe5591453be0e851057b50accd76db5a858ba1a8b809 */
SELECT * FROM ci_etl_db_dev.ci_capital_pipeline_consolidated
                WHERE CAST(extract_timestamp AS TIMESTAMP) = TIMESTAMP '2025-06-18 15:02:04'

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::924af7525d996e89eae2f3d11aabc0ba1f54edf0b9849206aad0624e34c22008 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-21' and end_date = '2025-04-21')
and start_date = '2025-04-21' and end_date = '2025-04-21'

/* cppi::f4e37535efb6796f29e4d49a70421cb9bbb3370ed66634a40bfe94135a20f0d3 */
SELECT * FROM "df_alternative_assets_qa"."private_equity_capital_usage_tracking"
where source = 'pe_pipeline' and fiscal_year = 'F26'

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::f0cc67136091b55d58276c632f885d362181840675228e701e35c343a5d48498 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-08' and end_date = '2025-04-08')
and start_date = '2025-04-08' and end_date = '2025-04-08'

/* cppi::50892fa8292836b3419abdf5232652954f837c9dea4123c14c9e5662706faab8 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-04-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-04-01'
    ) a
where arrival_time = max_publish

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

