/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::f2da25e990838955f7f23f7a10767a778f7c3d852d9297676a126249ad23325c */
select id_isin as identifier, cppib_sec_id as ID_CPPIBSEC, ticker_exch_cd as ticker from asset.qsrp_security_equity_latest
     where id_isin is not null and cppib_sec_id is not null

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::a341d1c4996e0fcd4dda854e75ce1430c71af794ee9c2653f784ed0b73469566 */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-17' and business_date <= date '2025-06-17' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

/* cppi::8b45a8c0ec099628da1b0aea99093e01137af07f0da7898ee01584443dfa1329 */
/* QuickSight cae221ec-4a42-4262-a9c1-b36fe7b883b0 */
SELECT "business_date", "year", "from_currency", "to_currency", "rate_type_code", "source", "bid_price", "ask_price", "mid_price", "factor", "inverse_quoted", "last_update_date", "vendor_file_name", "arrival_time"
FROM (SELECT *
FROM market.refinitiv_exchange_rates_wmr) AS "FX Rates - EUR, GBP, USD (PROD)"

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

/* cppi::899bf2b33ca262a2d389ee95ffad9874c63d88980933f2a9adf67eb7bb037256 */
select date_, security_id, gics_code from asset.qsrp_security_identifiers
                     where date_ between date '2025-06-16' and date '2025-06-17'

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::6ff692eee6ee40e0f4ff37c150cc5482cacce263758f6a4ad9aec585d50eaaed */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-04' and end_date = '2025-04-04')
and start_date = '2025-04-04' and end_date = '2025-04-04'

/* cppi::0468009adaee7a82d57b054440682765ba4bb10f7fe080e699b34c83234fd2b1 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-22' and end_date = '2025-04-22')
and start_date = '2025-04-22' and end_date = '2025-04-22'

/* cppi::1c23b6e45d601bf842946f983692ed3e97c5003145db096345935dfc78b9e41f */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-02-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-03-03'
    ) a
where arrival_time = max_publish

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
