/* cppi::c036bbe69a2a0e82723e7f6d5cf8203dd607a5934b86a764f7c084e86ea30121 */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-03' and business_date <= date '2025-06-17' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

/* cppi::6738c4ab657d4fca46fc023544d3335e0aadd904cc0ccfb7d47b1bc4bc9e1d58 */
